<div class="admin-bento"><div class="admin-bento-card admin-bento-card--wide"><div class="admin-card-head"><span class="admin-card-icon">🏢</span><h3>Details</h3></div><div class="admin-field-grid"><div class="field"><x-admin.label for="provider_number" required>Provider number</x-admin.label><input id="provider_number" name="provider_number" value="{{ old('provider_number', $provider->provider_number) }}" required></div><div class="field"><x-admin.label for="name" required>Name</x-admin.label><input id="name" name="name" value="{{ old('name', $provider->name) }}" required></div><div class="field"><x-admin.label for="email">Email</x-admin.label><input id="email" type="email" name="email" value="{{ old('email', $provider->email) }}"></div><div class="field"><x-admin.label for="phone">Phone</x-admin.label><input id="phone" name="phone" value="{{ old('phone', $provider->phone) }}"></div><div class="field full"><x-admin.label for="address">Provider address</x-admin.label><input id="address" name="address" value="{{ old('address', $provider->address) }}" placeholder="e.g. Cairo, Egypt"><small class="muted">Enter the normal address, then select the exact location below.</small></div></div></div><div class="admin-bento-card admin-bento-card--wide"><div class="admin-card-head"><span class="admin-card-icon cool">📍</span><h3>Location</h3></div><div class="admin-field-grid"><div class="field full provider-location-picker"><x-admin.label>Provider location on map</x-admin.label><div class="location-picker-help">Click the map or drag the pin to the provider location. This is used to show assigned classes on the operational map.</div><div id="providerLocationMap" class="provider-location-map" data-lat="{{ old('latitude', $provider->latitude) }}" data-lng="{{ old('longitude', $provider->longitude) }}"></div><div class="location-picker-actions"><button class="btn secondary" type="button" id="clearProviderLocation">Clear location</button><span id="providerLocationMessage" class="muted